{
  "title": "The Mirror Rescue of Cinderport",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a ruined city map at the edge of the fallen capital.",
      "visual_description": "Mara stands on a rubble-strewn hill, unfurling a torn parchment map while the broken spires of a royal city loom in the twilight.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp flickers a warning about the cursed tower ahead.",
      "visual_description": "Inside a collapsed guardhouse, the Oracle Lamp's single flame-eye pulses orange as it speaks, casting long shadows across the dusty floor.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Glass Diver tests a shattered window for a mirror-path.",
      "visual_description": "The Glass Diver presses a gloved hand against a cracked, grimy windowpane; his diving helmet reflects the fractured buildings behind him.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The Tin Fox scurries ahead and reports a sleeping figure near the city gate.",
      "visual_description": "The small clockwork fox crouches by the rusted portcullis, its blue glass eyes fixed on a slumped form snoring on a pile of stamped papers.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "Mara convinces the Sleeping Tax Collector to wake and share entry tokens.",
      "visual_description": "Mara shakes the tax collector's shoulder; he stirs groggily, a ledger book still under his cheek, as stacks of paper rustle.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The Glass Diver phases through a magical door sealed with ancient symbols.",
      "visual_description": "The Glass Diver steps into a shimmering windowpane set in a stone arch, his reflection rippling as he passes through the barrier.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp illuminates a hidden staircase beneath a collapsed throne room.",
      "visual_description": "The lamp's glow reveals a spiral stair descending into darkness, half-buried under fallen banners and shattered stone.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The Tin Fox scouts a courtyard filled with old royal banners and broken statues.",
      "visual_description": "The metal fox picks its way among tattered, dusty banners bearing faded crests, past toppled statues overgrown with moss.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara deciphers a warning carved into a ruined well about a dragon rumor.",
      "visual_description": "Mara traces eroded runes around a dry well while the Oracle Lamp hovers nearby, its flame casting dancing light on the carvings.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The Sleeping Tax Collector dozes off again atop a pile of old tax ledgers.",
      "visual_description": "In a dusty archive room, the collector curls up on a stack of leather-bound books, a half-eaten biscuit in his hand.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The Glass Diver swims through a mirror in a cursed tower to retrieve a rescue key.",
      "visual_description": "Inside a circular tower room, the Glass Diver reaches into a full-length mirror, his arm disappearing into silver light.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "Armored patrols march past a collapsed wall while the group hides in shadow.",
      "visual_description": "Three figures in full plate armor clank along a cracked street, their visors down; Mara and the Tin Fox press against a crumbling alcove.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The Oracle Lamp warns of a trap in the bell tower where the captive is held.",
      "visual_description": "The lamp's flame-eye narrows to a slit as it gazes up at a bell tower silhouette, its voice a low hiss.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The Sleeping Tax Collector is carried by the Tin Fox to a safe spot.",
      "visual_description": "The clockwork fox strains to drag the sleeping collector by his sleeve across a mosaic floor, leaving a trail of scattered papers.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The Glass Diver breaks a magical barrier in the tower by shattering a mirror.",
      "visual_description": "The Glass Diver strikes a massive oval mirror with a metal gauntlet, sending cracks across its surface and releasing a flash of light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Mara leads the group through a subterranean passage beneath the royal quarter.",
      "visual_description": "Mara holds a compass aloft, the Oracle Lamp lighting a low tunnel lined with old water pipes and roots.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The group emerges onto a bridge under a blood-red sky, pursued by armored patrols.",
      "visual_description": "A stone bridge arches over a dry moat; behind the group, armored figures pour from the gate; ahead, the bridge leads to open plains.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The Tin Fox triggers a bridge mechanism to collapse the span behind them.",
      "visual_description": "The fox bites a bronze lever at the bridge's midpoint; the stone section behind them groans and falls into the dust-filled chasm.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector"]
    }
  ],
  "gate_token": "1Eq7tDRMmVoMTeZ75oetQQ"
}

